using System.ComponentModel;
using System.Text;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API using HttpClient.
/// Constructor-injected HttpClient is resolved via DI and does NOT appear in the tool schema.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Retrieve a single resource by its ID.")]
    public async Task<string> GetResource(
        [Description("The unique identifier of the resource to retrieve")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("GET /api/resources/{Id}", id);
        var response = await httpClient.GetAsync($"api/resources/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("List resources with optional filtering by category.")]
    public async Task<string> ListResources(
        [Description("Filter by category (optional)")] string? category = null,
        [Description("Maximum number of results to return (1-100)")] int limit = 20,
        CancellationToken cancellationToken = default)
    {
        var query = category is not null ? $"?category={Uri.EscapeDataString(category)}&limit={limit}" : $"?limit={limit}";
        logger.LogInformation("GET /api/resources{Query}", query);

        var response = await httpClient.GetAsync($"api/resources{query}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new resource with the given name and content.")]
    public async Task<string> CreateResource(
        [Description("Name for the new resource")] string name,
        [Description("Body content of the resource")] string content,
        CancellationToken cancellationToken = default)
    {
        var payload = JsonSerializer.Serialize(new { name, content }, JsonOptions);
        logger.LogInformation("POST /api/resources");

        var response = await httpClient.PostAsync(
            "api/resources",
            new StringContent(payload, Encoding.UTF8, "application/json"),
            cancellationToken);

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

